  r.wArmor = skillVal(w.bonusArmorByLevel, lvl) + armorNow * skillVal(w.armorPercentByLevel, lvl) / 100;
  r.wMr = skillVal(w.bonusMrByLevel, lvl);
  this.bonusArmor = (this.bonusArmor || 0) + r.wArmor;
  this.bonusMr = (this.bonusMr || 0) + r.wMr;
