  if (item.onHitMagicDamagePassive) { const p = item.onHitMagicDamagePassive; parts.push(`이케시아의 이빨(기본 공격 시 온히트 마법 피해 +${p.flat}+주문력${Math.round(p.apPercent * 100)}%)`); }
